const DB_KEY='margin-canvas-v2';
let currentUser=null,remoteSyncTimer=null,recognitionWorker=null,recognitionRequestId=0,activeRecognitionRequestId=0,recognitionPending=new Map(),recognitionSelection=null,recognizerReady=false;
function storageKeyFor(user){return user?`${DB_KEY}:user:${user.id}`:DB_KEY;}
function loadBooksFromStorage(key){try{const value=JSON.parse(localStorage.getItem(key));return Array.isArray(value)&&value.length?value:[];}catch{return[];}}
function mergeBooks(localBooks,remoteBooks){const merged=new Map((localBooks||[]).filter(item=>item&&typeof item.id==='string').map(item=>[item.id,clone(item)]));for(const remote of remoteBooks||[]){if(remote&&typeof remote.id==='string'&&!merged.has(remote.id))merged.set(remote.id,clone(remote));}return [...merged.values()];}
const starterBook={id:'calc',title:'Calculus · Week 04',icon:'∫',nodes:[
 {id:'t1',type:'text',x:90,y:45,w:470,h:195,text:'Integration by substitution',style:'title'},
 {id:'t2',type:'text',x:95,y:115,w:490,h:205,text:'Today we looked at u-substitution — the chain rule in reverse.\n\nIf an integral contains a function and its derivative, substitute the inside function with u. Look for a composite function where the derivative of the inner part is nearby.'},
 {id:'e1',type:'equation',x:170,y:320,w:360,expr:'∫ 2x cos(x^2) dx'},
 {id:'t3',type:'text',x:95,y:435,w:460,text:'Let u = x², then du = 2x dx\n\n∫ cos(u) du = sin(u) + C\n\nThe key is spotting the inside function and checking that its derivative is present.'},
 {id:'g1',type:'graph',x:650,y:140,w:390,expr:'sin(x)'},
 {id:'c1',type:'code',x:640,y:480,w:420,code:'// Safe local math cell\nconst radius = 3\nconst area = pi * radius^2\nconsole.log(area)\nplot("sin(x)")'},
 {id:'e2',type:'equation',x:150,y:790,w:390,expr:'∫ (3x^2) / (x^3 + 1) dx'}
]};
let books;try{const parsed=JSON.parse(localStorage.getItem(DB_KEY));books=Array.isArray(parsed)&&parsed.length?parsed:[starterBook];}catch{books=[starterBook];}for(const item of books){item.nodes ||= [];item.strokes ||= [];}
let book=books[0];if(!Array.isArray(book.nodes))book.nodes=[];
let selectedTool='select',selectedIds=new Set(),undoStack=[],editingSnapshot=null,camera={x:0,y:0,zoom:1},pointer=null,lastTap=0,aiReady=false,visionReady=false,searchIndex=[];
const workspace=document.getElementById('workspace'),world=document.getElementById('canvas-world'),nodesLayer=document.getElementById('canvas-nodes'),ink=document.getElementById('ink-canvas'),ctx=ink.getContext('2d'),lasso=document.getElementById('lasso-box');
const chat=document.getElementById('chat-history'),chatInput=document.getElementById('chat-input');
function clone(value){return JSON.parse(JSON.stringify(value));}
function save(){try{localStorage.setItem(storageKeyFor(currentUser),JSON.stringify(books));if(!currentUser)localStorage.setItem(DB_KEY,JSON.stringify(books));document.getElementById('save-label').textContent=currentUser?'Saved · syncing…':'Saved on this device';if(currentUser){clearTimeout(remoteSyncTimer);remoteSyncTimer=setTimeout(syncNotebooks,700);}}catch{document.getElementById('save-label').textContent='Storage full · export notebook';}}
function pushUndo(snapshot=null){undoStack.push(snapshot||{bookId:book.id,nodes:clone(book.nodes),strokes:clone(book.strokes||[])});if(undoStack.length>40)undoStack.shift();document.getElementById('undo-button').disabled=false;}
function trackNodeEdit(element,node,read){element.addEventListener('focus',()=>{editingSnapshot={bookId:book.id,nodeId:node.id,nodes:clone(book.nodes),strokes:clone(book.strokes||[]),value:read()};});element.addEventListener('blur',()=>{const before=editingSnapshot;editingSnapshot=null;if(before?.bookId===book.id&&before.nodeId===node.id&&before.value!==read())pushUndo({bookId:before.bookId,nodes:before.nodes,strokes:before.strokes});});}
function undo(){const previous=undoStack.pop();if(!previous||previous.bookId!==book.id)return;book.nodes=previous.nodes;book.strokes=previous.strokes;selectedIds.clear();document.getElementById('undo-button').disabled=!undoStack.length;showSelection();renderNodes();redrawInk();updateContext();save();}
function escapeHtml(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function nodeById(id){return book.nodes.find(node=>node.id===id);}
function renderBooks(){const list=document.getElementById('note-list');list.innerHTML=books.map(item=>`<button class="note-item ${item.id===book.id?'active':''}" data-book="${escapeHtml(item.id)}"><span class="note-emoji">${escapeHtml(item.icon||'∫')}</span><span>${escapeHtml(item.title)}</span></button>`).join('');list.querySelectorAll('[data-book]').forEach(button=>button.addEventListener('click',()=>switchBook(button.dataset.book)));document.getElementById('crumb-title').textContent=book.title;document.getElementById('context-summary').textContent=book.title;renderLibrary();}
function applyCamera(){world.style.transform=`translate(${camera.x}px,${camera.y}px) scale(${camera.zoom})`;document.getElementById('zoom-label').textContent=`${Math.round(camera.zoom*100)}%`;}
function clientToWorld(x,y){const rect=workspace.getBoundingClientRect();return{x:(x-rect.left-camera.x)/camera.zoom,y:(y-rect.top-camera.y)/camera.zoom};}
function worldCenter(){const rect=workspace.getBoundingClientRect();return clientToWorld(rect.left+rect.width/2,rect.top+rect.height/2);}
function renderNodes(){nodesLayer.replaceChildren();for(const node of book.nodes){const element=document.createElement('article');element.className=`canvas-node ${node.type}-node ${selectedIds.has(node.id)?'selected':''}`;element.dataset.id=node.id;element.style.left=`${node.x}px`;element.style.top=`${node.y}px`;if(node.w)element.style.width=`${node.w}px`;
 if(node.type==='text'){
  if(node.style==='title')element.classList.add('title-node');element.setAttribute('aria-label','Canvas text note');element.innerHTML=`<button class="node-drag-handle" type="button" title="Move note" aria-label="Move note">⠿</button><div class="text-content" contenteditable="true" spellcheck="true" data-placeholder="Type notes here…"></div>`;const editor=element.querySelector('.text-content');editor.textContent=node.text||'';
  trackNodeEdit(editor,node,()=>editor.innerText);editor.addEventListener('input',()=>{node.text=editor.innerText;save();updateContext();scheduleCheck();});editor.addEventListener('keydown',event=>{if(event.key==='Escape'){editor.blur();}});editor.addEventListener('pointerdown',event=>event.stopPropagation());element.querySelector('.node-drag-handle').addEventListener('pointerdown',event=>startNodeDrag(event,node));
 }else if(node.type==='equation'){
  element.innerHTML=`<div class="node-label">EQUATION · LOCAL CHECK</div><input class="equation-input" aria-label="Equation" value="${escapeHtml(node.expr||'')}" placeholder="e.g. 2x + 4 = 18"><div class="equation-result"></div><button class="node-remove" title="Delete equation">×</button>`;
  const input=element.querySelector('input');trackNodeEdit(input,node,()=>input.value);input.addEventListener('input',()=>{node.expr=input.value;save();checkEquationNode(node,element);updateContext();scheduleCheck();});input.addEventListener('pointerdown',event=>event.stopPropagation());input.addEventListener('keydown',event=>{if(event.key==='Enter')input.blur();});element.querySelector('.node-remove').addEventListener('click',()=>removeNode(node.id));checkEquationNode(node,element);
 }else if(node.type==='graph'){
  element.innerHTML=`<div class="graph-node-head"><label>⌁ &nbsp;y = <input class="graph-expression" aria-label="Graph expression" value="${escapeHtml(node.expr||'sin(x)')}"></label><button type="button" title="Remove graph" aria-label="Remove graph">×</button></div><canvas></canvas>`;const expression=element.querySelector('.graph-expression'),graphCanvas=element.querySelector('canvas');element.querySelector('button').addEventListener('click',()=>removeNode(node.id));trackNodeEdit(expression,node,()=>expression.value);expression.addEventListener('input',()=>{node.expr=expression.value;save();try{window.MarginMath.plot(graphCanvas,node.expr||'sin(x)');expression.setCustomValidity('');}catch(error){expression.setCustomValidity(error.message);}});expression.addEventListener('pointerdown',event=>event.stopPropagation());expression.addEventListener('keydown',event=>{if(event.key==='Enter')expression.blur();});
  requestAnimationFrame(()=>{try{window.MarginMath.plot(graphCanvas,node.expr||'sin(x)');}catch{}});
 }else if(node.type==='code'){
  element.innerHTML=`<div class="node-head"><span>▤ &nbsp; CALCULATION CELL</span><button class="node-remove" title="Remove code cell">×</button></div><textarea class="code-input" spellcheck="false" aria-label="JavaScript calculation">${escapeHtml(node.code||'')}</textarea><div class="code-run"><button class="run-button">▶ Run</button><span class="code-status">Safe math interpreter · no JS execution</span><span class="code-output"></span></div><canvas hidden></canvas>`;
  element.querySelector('.node-remove').addEventListener('click',()=>removeNode(node.id));const area=element.querySelector('textarea');trackNodeEdit(area,node,()=>area.value);area.addEventListener('input',()=>{node.code=area.value;save();});area.addEventListener('pointerdown',event=>event.stopPropagation());element.querySelector('.run-button').addEventListener('click',()=>runCodeCell(node,element));
 }else if(node.type==='media'){
  const source=node.data||'';const figure=document.createElement('figure');figure.className='media-node';if(node.mime?.startsWith('image/')){const image=document.createElement('img');image.src=source;image.alt=node.name||'Imported image';figure.append(image);}else{const embed=document.createElement('embed');embed.src=source;embed.type=node.mime||'application/pdf';embed.title=node.name||'Imported file';figure.append(embed);}const caption=document.createElement('figcaption');caption.textContent=node.name||'Imported file';figure.append(caption);element.replaceWith(figure);figure.classList.add('canvas-node');figure.dataset.id=node.id;figure.style.left=`${node.x}px`;figure.style.top=`${node.y}px`;if(node.w)figure.style.width=`${node.w}px`;figure.addEventListener('pointerdown',event=>startNodeDrag(event,node));nodesLayer.append(figure);continue;
 }
 element.addEventListener('pointerdown',event=>{if(selectedTool==='select'&&!(event.target.matches('input,textarea,button')||event.target.isContentEditable)&&(!event.target.closest('[contenteditable=true]')))startNodeDrag(event,node);});nodesLayer.append(element);
 }
}
function checkEquationNode(node,element){const result=element.querySelector('.equation-result');if(!result)return;const parts=(node.expr||'').split('=');if(parts.length!==2||!parts[0].trim()||!parts[1].trim()){result.classList.remove('issue');result.textContent='Enter an equality (left = right) for a local numerical check.';return;}try{const left=window.MarginMath.compile(parts[0]),right=window.MarginMath.compile(parts[1]);const samples=[0,1,-1,2,-2,0.5,Math.PI];const mismatch=samples.some(x=>{const a=left(x),b=right(x);return Number.isFinite(a)&&Number.isFinite(b)&&Math.abs(a-b)>1e-7*Math.max(1,Math.abs(a),Math.abs(b));});result.classList.toggle('issue',mismatch);result.textContent=mismatch?'Possible mismatch: both sides differ for a test value. Check this step.':'No mismatch found in sampled values; this is not a symbolic proof.';}catch(error){result.classList.remove('issue');result.textContent=`Local check unavailable: ${error.message}`;}}
function addNode(type,options={}){pushUndo();const center=worldCenter();const node={id:`n-${crypto.randomUUID?.()||Date.now()+Math.random()}`,type,x:center.x+(Math.random()-0.5)*100,y:center.y+(Math.random()-0.5)*70,...options};book.nodes.push(node);renderNodes();save();updateContext();const element=nodesLayer.querySelector(`[data-id="${node.id}"]`);if(type==='text'){const editor=element.querySelector('.text-content');editor?.focus();if(editor){const selection=getSelection();const range=document.createRange();range.selectNodeContents(editor);range.collapse(false);selection.removeAllRanges();selection.addRange(range);}}else element?.querySelector('input,textarea')?.focus();return node;}
function removeNode(id){pushUndo();book.nodes=book.nodes.filter(node=>node.id!==id);selectedIds.delete(id);showSelection();save();updateContext();}
function startNodeDrag(event,node){if(selectedTool!=='select'&&selectedTool!=='lasso')return;if(event.button!==0)return;event.preventDefault();event.stopPropagation();if(!selectedIds.has(node.id)){selectedIds.clear();selectedIds.add(node.id);renderNodes();}const start=clientToWorld(event.clientX,event.clientY);const origins=[...selectedIds].map(id=>{const item=nodeById(id);return{id,x:item.x,y:item.y};}).filter(item=>nodeById(item.id));if(!origins.length)return;pushUndo();pointer={kind:'nodes',start,origins,pointerId:event.pointerId};workspace.setPointerCapture(event.pointerId);}
function addText(text,x,y,style){pushUndo();book.nodes.push({id:`n-${Date.now()}-${Math.random()}`,type:'text',x,y,w:470,text,style});renderNodes();save();updateContext();}
function resizeInk(){const rect=workspace.getBoundingClientRect();const scale=Math.min(devicePixelRatio||1,2);ink.width=Math.round(rect.width*scale);ink.height=Math.round(rect.height*scale);ctx.setTransform(scale,0,0,scale,0,0);redrawInk();}
function redrawInk(){const scale=Math.min(devicePixelRatio||1,2);ctx.clearRect(0,0,ink.width/scale,ink.height/scale);ctx.save();ctx.translate(camera.x,camera.y);ctx.scale(camera.zoom,camera.zoom);for(const stroke of book.strokes||[]){if(!stroke.points?.length)continue;ctx.beginPath();ctx.strokeStyle=stroke.color;ctx.lineWidth=stroke.width;ctx.lineCap='round';ctx.lineJoin='round';stroke.points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();}if(pointer?.kind==='stroke'&&pointer.points.length){ctx.beginPath();ctx.strokeStyle=pointer.color;ctx.lineWidth=pointer.width;ctx.lineCap='round';ctx.lineJoin='round';pointer.points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();}ctx.restore();}
function setTool(tool){selectedTool=tool;document.querySelectorAll('[data-tool]').forEach(button=>button.classList.toggle('active',button.dataset.tool===tool));workspace.classList.toggle('ink-on',['pen','highlighter','eraser','lasso','recognize','ai-drawing'].includes(tool));const labels={select:'Select · drag notes to move or empty space to pan',pen:'Pen · draw with stylus, touch, or mouse',highlighter:'Highlighter · mark up the page',eraser:'Eraser · erase a stroke where you touch',lasso:'Lasso · drag around notes to select them',recognize:'Read ink · drag around one handwritten line', 'ai-drawing':'AI drawing · select an area to ask about it'};document.getElementById('status-tool').textContent=labels[tool]||tool;if(tool==='recognize')document.getElementById('insight-copy').textContent='Drag a box around one handwritten text line. Recognition runs in your browser; review the result before adding it.';if(tool==='ai-drawing')document.getElementById('insight-copy').textContent='Drag around handwriting, a sketch, or a worked step to ask your configured AI provider about that image. Sharing requires opt-in.';}
function pointerDown(event){if(event.target.closest('.canvas-toolbar,.zoom-controls,.selection-bar'))return;const now=Date.now();if(event.pointerType==='touch'&&event.isPrimary===false)return;lastTap=now;if(selectedTool==='recognize'||selectedTool==='ai-drawing'){event.preventDefault();workspace.setPointerCapture(event.pointerId);const point=clientToWorld(event.clientX,event.clientY);pointer={kind:selectedTool==='ai-drawing'?'ai-drawing':'recognize',start:point,end:point,startClient:{x:event.clientX,y:event.clientY},pointerId:event.pointerId};updateRecognitionBox(event.clientX,event.clientY,event.clientX,event.clientY);return;}if(selectedTool==='pen'||selectedTool==='highlighter'){event.preventDefault();workspace.setPointerCapture(event.pointerId);pushUndo();const p=clientToWorld(event.clientX,event.clientY);pointer={kind:'stroke',points:[p],color:selectedTool==='highlighter'?'#55c9ff55':'#c2ddff',width:(selectedTool==='highlighter'?13:2.2)*(1/camera.zoom)*(event.pressure?0.75+event.pressure:1),pointerId:event.pointerId};redrawInk();return;}if(selectedTool==='eraser'){event.preventDefault();workspace.setPointerCapture(event.pointerId);pointer={kind:'erase',pointerId:event.pointerId,changed:false};eraseAt(event.clientX,event.clientY);return;}if(selectedTool==='lasso'){event.preventDefault();workspace.setPointerCapture(event.pointerId);const p=clientToWorld(event.clientX,event.clientY);pointer={kind:'lasso',start:p,end:p,startClient:{x:event.clientX,y:event.clientY}};return;}if(selectedTool==='select'){if(event.target===workspace||event.target===ink){event.preventDefault();workspace.setPointerCapture(event.pointerId);pointer={kind:'pan',startX:event.clientX,startY:event.clientY,cameraX:camera.x,cameraY:camera.y};}}}
function pointerMove(event){if(!pointer)return;if(pointer.kind==='erase'){eraseAt(event.clientX,event.clientY);}else if(pointer.kind==='stroke'){const point=clientToWorld(event.clientX,event.clientY);if(!pointer.points.length||Math.hypot(point.x-pointer.points.at(-1).x,point.y-pointer.points.at(-1).y)>.5)pointer.points.push(point);redrawInk();}else if(pointer.kind==='pan'){camera.x=pointer.cameraX+event.clientX-pointer.startX;camera.y=pointer.cameraY+event.clientY-pointer.startY;applyCamera();redrawInk();}else if(pointer.kind==='nodes'){const current=clientToWorld(event.clientX,event.clientY);for(const origin of pointer.origins){const node=nodeById(origin.id);if(node){node.x=origin.x+(current.x-pointer.start.x);node.y=origin.y+(current.y-pointer.start.y);for(const element of nodesLayer.children)if(element.dataset.id===node.id){element.style.left=`${node.x}px`;element.style.top=`${node.y}px`;break;}}}}else if(pointer.kind==='lasso'){pointer.end=clientToWorld(event.clientX,event.clientY);const rect=workspace.getBoundingClientRect(),x=Math.min(pointer.startClient.x,event.clientX)-rect.left,y=Math.min(pointer.startClient.y,event.clientY)-rect.top,w=Math.abs(pointer.startClient.x-event.clientX),h=Math.abs(pointer.startClient.y-event.clientY);lasso.style.display='block';lasso.style.left=`${x}px`;lasso.style.top=`${y}px`;lasso.style.width=`${w}px`;lasso.style.height=`${h}px`;lasso.style.transform='none';}else if(pointer.kind==='recognize'||pointer.kind==='ai-drawing'){pointer.end=clientToWorld(event.clientX,event.clientY);updateRecognitionBox(pointer.startClient.x,pointer.startClient.y,event.clientX,event.clientY);}}
function pointerUp(){if(!pointer)return;const finished=pointer;pointer=null;if(finished.kind==='stroke'){if(finished.points.length===1)finished.points.push({...finished.points[0],x:finished.points[0].x+.01});book.strokes ||= [];book.strokes.push({points:finished.points,color:finished.color,width:finished.width});save();updateContext();}else if(finished.kind==='erase'){if(finished.changed){save();updateContext();}}else if(finished.kind==='nodes'){renderNodes();save();updateContext();}else if(finished.kind==='lasso'){const a=finished.start,b=finished.end,x=Math.min(a.x,b.x),y=Math.min(a.y,b.y),w=Math.abs(a.x-b.x),h=Math.abs(a.y-b.y);selectedIds.clear();for(const node of book.nodes){const bounds=nodeBounds(node);if(bounds.x<=x+w&&bounds.x+bounds.w>=x&&bounds.y<=y+h&&bounds.y+bounds.h>=y)selectedIds.add(node.id);}lasso.style.display='none';showSelection();}else if(finished.kind==='recognize'||finished.kind==='ai-drawing'){const a=finished.start,b=finished.end;const rect={x:Math.min(a.x,b.x),y:Math.min(a.y,b.y),w:Math.abs(a.x-b.x),h:Math.abs(a.y-b.y)};document.getElementById('recognition-box').classList.remove('visible');setTool('select');if(rect.w>12&&rect.h>8){if(finished.kind==='recognize')prepareRecognition(rect);else prepareDrawingAnalysis(rect);}else addChat('assistant',finished.kind==='recognize'?'The selection was too small. Choose Read ink and drag around one line of handwriting.':'The selection was too small. Choose AI drawing and drag around a sketch or worked step.');}redrawInk();}
function nodeBounds(node){const width=node.w||420,height=node.type==='graph'?255:node.type==='code'?185:node.type==='media'?300:node.type==='equation'?112:Math.max(80,(String(node.text||'').split(/\n/).length)*27);return{x:node.x-width/2,y:node.y-height/2,w:width,h:height};}
function eraseAt(clientX,clientY){if(!pointer||pointer.kind!=='erase')return;const point=clientToWorld(clientX,clientY),radius=18/camera.zoom,strokes=book.strokes||[];for(let index=strokes.length-1;index>=0;index--){const stroke=strokes[index];if(stroke.points?.some((sample,i)=>i?distanceToSegment(point,stroke.points[i-1],sample)<radius:Math.hypot(sample.x-point.x,sample.y-point.y)<radius)){if(!pointer.changed){pointer.snapshot={bookId:book.id,nodes:clone(book.nodes),strokes:clone(book.strokes||[])};pointer.changed=true;pushUndo(pointer.snapshot);}strokes.splice(index,1);}}if(pointer.changed)redrawInk();}
function distanceToSegment(point,start,end){const dx=end.x-start.x,dy=end.y-start.y,length=dx*dx+dy*dy;if(!length)return Math.hypot(point.x-start.x,point.y-start.y);const t=Math.max(0,Math.min(1,((point.x-start.x)*dx+(point.y-start.y)*dy)/length));return Math.hypot(point.x-(start.x+t*dx),point.y-(start.y+t*dy));}
function showSelection(){const bar=document.getElementById('selection-bar'),content=[...selectedIds].map(nodeById).filter(Boolean);bar.hidden=!content.length;document.getElementById('selection-count').textContent=`${content.length} selected`;document.getElementById('selection-latex').disabled=!content.length;document.getElementById('selection-delete').disabled=!content.length;renderNodes();}
function getSelectedContent(){return [...selectedIds].map(id=>nodeById(id)).filter(Boolean).map(node=>node.type==='text'?node.text:node.type==='equation'?node.expr:node.type==='code'?node.code:`${node.type} ${node.expr||''}`).join('\n');}
function selectedLatex(){const selected=[...selectedIds].map(nodeById).filter(node=>node?.type==='equation');if(!selected.length)return getSelectedContent().trim();return selected.map(node=>`\\(${node.expr.replace(/\s*=/g,' = ')}\\)`).join('\n');}
function setModal(title,kicker,html){document.getElementById('modal-title').textContent=title;document.getElementById('modal-kicker').textContent=kicker;document.getElementById('modal-content').innerHTML=html;document.getElementById('modal-scrim').hidden=false;}
function openAccount(mode='login'){setPage('canvas');const signedIn=Boolean(currentUser);if(signedIn){setModal('Your Margin account','ACCOUNT · NOTEBOOK SYNC',`<p class="modal-hint">Signed in as <strong>${escapeHtml(currentUser.email)}</strong>. Your notebook syncs to this server when you make changes.</p><div class="modal-actions"><button id="sync-now">Sync now</button><button id="sign-out">Sign out</button></div><p class="modal-hint">Your browser keeps a local copy too. This self-hosted server stores account data in its private .data folder.</p>`);document.getElementById('sync-now').onclick=async()=>{await syncNotebooks(true);};document.getElementById('sign-out').onclick=signOut;return;}renderAuthForm(mode);}
function renderAuthForm(mode){const signup=mode==='signup';setModal(signup?'Create your account':'Sign in to Margin','ACCOUNT · PRIVATE NOTEBOOK SYNC',`<p class="modal-hint">${signup?'Create an account to sync notebooks across browsers using this server. Your current local notes will be kept.':'Sign in to sync your notes with this server. This browser also keeps its local copy.'}</p><form class="account-form" id="account-form"><label>Email<input id="auth-email" type="email" autocomplete="email" maxlength="254" required></label><label>Password<input id="auth-password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="${signup?12:1}" maxlength="128" required>${signup?'<small>Use at least 12 characters.</small>':''}</label><div class="auth-error" id="auth-error" role="alert"></div><button class="auth-submit" type="submit">${signup?'Create account':'Sign in'}</button></form><button class="auth-switch" id="auth-switch" type="button">${signup?'Already have an account? Sign in':'New here? Create an account'}</button><p class="modal-hint">No email is sent; this is a local account on the server running this app. Use HTTPS if exposing it beyond your computer.</p>`);document.getElementById('auth-switch').onclick=()=>renderAuthForm(signup?'login':'signup');document.getElementById('account-form').addEventListener('submit',async event=>{event.preventDefault();const error=document.getElementById('auth-error'),submit=event.currentTarget.querySelector('[type=submit]');submit.disabled=true;error.textContent='';const submittedEmail=document.getElementById('auth-email').value,submittedPassword=document.getElementById('auth-password').value;try{const response=await fetch(signup?'/api/auth/signup':'/api/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email:submittedEmail,password:submittedPassword})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not sign in.');await activateUser(data.user,signup);closeModal();}catch(reason){error.textContent=reason.message;}finally{if(submit.isConnected)submit.disabled=false;}});}
function updateAccountUi(){const label=currentUser?.email||'Guest workspace',detail=currentUser?'Account · syncing on this server':'Local · no account';document.getElementById('profile-name').textContent=label;document.getElementById('sidebar-account').title=currentUser?`Account: ${currentUser.email}`:'Sign in to sync your notebooks';document.getElementById('account-open').title=currentUser?'Account and notebook sync':'Sign in to sync notebooks';document.getElementById('profile-detail').textContent=detail;document.getElementById('account-label').textContent=currentUser?'Account':'Sign in';document.getElementById('sync-status').textContent=currentUser?'Account sync enabled · local copy kept':'Local notebook · saved here';document.getElementById('save-label').textContent=currentUser?'Synced to this device':'Saved on this device';}
function renderLibrary(){const grid=document.getElementById('library-grid');if(!grid)return;grid.innerHTML=books.map(item=>`<button class="library-card" data-library-book="${escapeHtml(item.id)}"><span>${escapeHtml(item.icon||'✎')}</span><strong>${escapeHtml(item.title||'Untitled notebook')}</strong><small>${(item.nodes||[]).length} canvas items · ${(item.strokes||[]).length} ink strokes</small><span class="book-date">${item.id===book.id?'CURRENT NOTEBOOK':'Open notebook'}</span></button>`).join('')||'<p class="modal-hint">No notebooks yet. Create one from Canvas.</p>';grid.querySelectorAll('[data-library-book]').forEach(button=>button.onclick=()=>{switchBook(button.dataset.libraryBook);setPage('canvas');});}
function switchBook(id){save();book=books.find(item=>item.id===id)||book;book.nodes||=[];book.strokes||=[];selectedIds.clear();undoStack=[];editingSnapshot=null;document.getElementById('undo-button').disabled=true;showSelection();renderBooks();redrawInk();updateContext();renderLibrary();}
function setPage(name){document.querySelectorAll('.workspace-tab').forEach(tab=>{const active=tab.dataset.page===name;tab.classList.toggle('active',active);tab.setAttribute('aria-selected',String(active));});document.querySelectorAll('.tab-page').forEach(page=>{const active=page.id===`page-${name}`;page.classList.toggle('active',active);page.hidden=!active;});if(name==='library')renderLibrary();if(name==='canvas'){requestAnimationFrame(()=>{resizeInk();renderNodes();});}document.getElementById('sidebar').classList.remove('mobile-visible');}
async function activateUser(user,importGuestBooks=false){clearTimeout(remoteSyncTimer);const guestBooks=books.map(item=>clone(item));currentUser=user;const localBooks=loadBooksFromStorage(storageKeyFor(user));if(localBooks.length)books=importGuestBooks?mergeBooks(guestBooks,localBooks):localBooks;else if(importGuestBooks&&guestBooks.length)books=guestBooks;else books=[];for(const item of books){item.nodes ||= [];item.strokes ||= [];}book=books[0]||{id:`first-${Date.now()}`,title:'My first notebook',icon:'✎',nodes:[],strokes:[]};book.nodes||=[];book.strokes||=[];selectedIds.clear();undoStack=[];editingSnapshot=null;document.getElementById('undo-button').disabled=true;localStorage.setItem(storageKeyFor(user),JSON.stringify(books));renderBooks();renderNodes();resizeInk();redrawInk();updateContext();updateAccountUi();closeModal();await syncNotebooks(false,!localBooks.length&&!importGuestBooks);}
async function signOut(){clearTimeout(remoteSyncTimer);const signingOutUser=currentUser;try{await fetch('/api/auth/logout',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});}catch{}if(signingOutUser&&currentUser?.id!==signingOutUser.id)return;currentUser=null;books=loadBooksFromStorage(DB_KEY);if(!books.length)books=[starterBook];for(const item of books){item.nodes ||= [];item.strokes ||= [];}book=books[0];book.nodes||=[];book.strokes||=[];selectedIds.clear();undoStack=[];editingSnapshot=null;document.getElementById('undo-button').disabled=true;renderBooks();renderNodes();resizeInk();redrawInk();updateContext();updateAccountUi();closeModal();}
async function syncNotebooks(showErrors=false,preferRemote=false){if(!currentUser)return;const syncingUser=currentUser;const syncLabel=document.getElementById('sync-status');try{const get=await fetch('/api/notebooks',{cache:'no-store'});if(currentUser?.id!==syncingUser.id)return;if(get.status===401){currentUser=null;updateAccountUi();return;}const remoteData=await get.json();if(!get.ok)throw new Error(remoteData.error||'Could not load server notebooks.');const merged=preferRemote?mergeBooks(remoteData.notebooks,books):mergeBooks(books,remoteData.notebooks);if(currentUser?.id!==syncingUser.id)return;if(JSON.stringify(merged)!==JSON.stringify(books)){books=merged;if(!books.length)books=[clone(book)];if(!books.some(item=>item.id===book?.id))book=books[0];else book=books.find(item=>item.id===book.id);book.nodes||=[];book.strokes||=[];renderBooks();renderNodes();redrawInk();updateContext();renderLibrary();}if(currentUser?.id!==syncingUser.id)return;const put=await fetch('/api/notebooks',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({notebooks:books})});const result=await put.json();if(currentUser?.id!==syncingUser.id)return;if(!put.ok)throw new Error(result.error||'Could not save notebooks to server.');localStorage.setItem(storageKeyFor(syncingUser),JSON.stringify(books));syncLabel.textContent=`Synced · ${result.count} notebook${result.count===1?'':'s'}`;document.getElementById('save-label').textContent='Synced securely';}catch(error){syncLabel.textContent='Sync paused · local copy safe';document.getElementById('save-label').textContent='Saved locally · sync paused';if(showErrors){setModal('Sync needs attention','ACCOUNT · NOTEBOOK SYNC',`<p class="modal-hint">${escapeHtml(error.message)} Your local copy is still available in this browser.</p><div class="modal-actions"><button id="sync-retry">Try again</button></div>`);document.getElementById('sync-retry').onclick=()=>syncNotebooks(true);}}}
function updateRecognitionBox(x1,y1,x2,y2){const box=document.getElementById('recognition-box'),rect=workspace.getBoundingClientRect();box.classList.add('visible');box.style.left=`${Math.min(x1,x2)-rect.left}px`;box.style.top=`${Math.min(y1,y2)-rect.top}px`;box.style.width=`${Math.abs(x2-x1)}px`;box.style.height=`${Math.abs(y2-y1)}px`;}
function startRecognition(){setPage('canvas');setTool('recognize');addChat('assistant','Select Read ink, then drag around one handwritten prose line. Review the result before inserting it. The first model load is about 70 MB and needs internet; equations may need correction.');}
function prepareRecognition(rect){if(recognitionWorker){recognizerReady=false;addChat('assistant','Read two more lines if the first one was not clear. Each new selection starts a fresh request.');}const pad=14,scale=Math.max(.25,Math.min(2,8192/Math.max(1,rect.w+pad*2),8192/Math.max(1,rect.h+pad*2))),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.ceil((rect.w+pad*2)*scale));canvas.height=Math.max(1,Math.ceil((rect.h+pad*2)*scale));const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,canvas.width,canvas.height);c.strokeStyle='#111';c.lineCap='round';c.lineJoin='round';for(const stroke of book.strokes||[]){if(!stroke.points?.length)continue;c.beginPath();let started=false;for(const p of stroke.points){if(p.x>=rect.x-pad&&p.x<=rect.x+rect.w+pad&&p.y>=rect.y-pad&&p.y<=rect.y+rect.h+pad){const x=(p.x-rect.x+pad)*scale,y=(p.y-rect.y+pad)*scale;if(!started){c.moveTo(x,y);started=true;}else c.lineTo(x,y);}else started=false;}c.lineWidth=Math.max(1,stroke.width*scale);c.stroke();}for(const node of book.nodes){if(node.type!=='text')continue;const x=node.x-(node.w||420)/2;if(x>rect.x+rect.w||x+(node.w||420)<rect.x||node.y<rect.y||node.y>rect.y+rect.h)continue;c.fillStyle='#111';c.font='16px Georgia';String(node.text||'').split(/\n/).forEach((line,index)=>c.fillText(line,(x-rect.x+pad)*scale,(node.y-rect.y+pad+20+index*25)*scale));}recognitionSelection={rect,image:canvas.toDataURL('image/png'),requestId:++recognitionRequestId};showRecognitionReview();if(document.getElementById('ocr-result')){document.getElementById('ocr-result').value='';document.getElementById('ocr-result').placeholder='Recognition result will appear here…';document.getElementById('ocr-status').textContent='Starting a new selection…';}}
function showRecognitionReview(){if(!recognitionSelection)return;setModal('Review handwriting','READ INK · LOCAL RECOGNITION',`<div class="recognition-notice">Your ink image is processed on this device. It is sent to no server. Recognition is designed for one English text line and can make mistakes; handwritten equations may need manual correction.</div><p class="modal-hint" id="ocr-status">Loading the handwriting model (first use downloads about 70 MB)…</p><img class="recognition-preview" src="${recognitionSelection.image}" alt="Selected handwritten area"><label class="recognition-form">Recognized text · review and edit<textarea id="ocr-result" placeholder="Recognition result will appear here…"></textarea></label><div class="modal-actions"><button id="ocr-insert" disabled>Insert as note</button><button id="ocr-retry">Recognize again</button></div>`);document.getElementById('ocr-result').addEventListener('input',event=>{document.getElementById('ocr-insert').disabled=!event.target.value.trim();});document.getElementById('ocr-insert').onclick=()=>{const text=document.getElementById('ocr-result').value.trim();if(!text)return;const {rect}=recognitionSelection;addText(text,rect.x+rect.w/2,rect.y+rect.h+55);closeModal();};document.getElementById('ocr-retry').onclick=()=>runRecognition();runRecognition();}
async function runRecognition(){const status=document.getElementById('ocr-status'),result=document.getElementById('ocr-result'),insert=document.getElementById('ocr-insert'),selection=recognitionSelection;if(!status||!selection)return;status.textContent='Loading the on-device handwriting recognizer…';insert.disabled=true;const id=++recognitionRequestId;activeRecognitionRequestId=id;try{if(!recognitionWorker){recognitionWorker=new Worker('ocr-worker.js',{type:'module'});recognitionWorker.onmessage=event=>{const data=event.data;if(data.type==='progress'){if(data.id===activeRecognitionRequestId){const el=document.getElementById('ocr-status');if(el)el.textContent=data.message;}return;}const pending=recognitionPending.get(data.id);if(!pending)return;recognitionPending.delete(data.id);if(data.error)pending.reject(new Error(data.error));else pending.resolve(data.text||'');};recognitionWorker.onerror=()=>{for(const item of recognitionPending.values())item.reject(new Error('The model worker could not start. Try a modern browser with WebAssembly enabled.'));recognitionPending.clear();};}const text=await new Promise((resolve,reject)=>{recognitionPending.set(id,{resolve,reject});recognitionWorker.postMessage({id,image:selection.image});});if(activeRecognitionRequestId!==id||!document.getElementById('ocr-result'))return;result.value=text;insert.disabled=!text.trim();status.textContent=text?'Recognition is ready. Correct any mistakes, then add it as editable note text.':'No text was detected. Try a tighter selection with higher-contrast writing.';}catch(error){if(activeRecognitionRequestId===id&&status)status.textContent=`Recognition unavailable: ${error.message}. Your ink has not left this device. You can still type into the box above.`;}}
function setStudyResult(text){document.getElementById('study-result').textContent=text;}
async function initializeAccount(){try{const response=await fetch('/api/auth/me',{cache:'no-store'}),data=await response.json();if(data.user)await activateUser(data.user);else updateAccountUi();}catch{updateAccountUi();}}
function runStudyAction(action){const note=book.nodes.map(node=>node.type==='text'?node.text:node.type==='equation'?`Equation: ${node.expr}`:'').filter(Boolean).join('\n');if(action==='hint'){const hint=note?`Hint · ${book.title}\nLook at the latest equation. Which operation would preserve equality on both sides? Try that before simplifying further.`:'Add a note or equation to the canvas first; then your hint can use its context.';setStudyResult(hint);addChat('assistant',hint);}else if(action==='summary'){const summary=note?`Local recap · ${book.title}\n\n${note.slice(0,1600)}`:'There is no typed content to recap yet. Read ink can transcribe a handwritten line into editable text.';setStudyResult(summary);addChat('assistant',summary);}else if(action==='practice')openPractice();else if(action==='account')openAccount();else if(action==='export')exportNotebook();else if(action==='assistant'){setPage('canvas');const panel=document.getElementById('assistant-panel');panel.classList.remove('closed');if(innerWidth<=620)panel.classList.add('mobile-open');}else if(action==='recognize'){setPage('canvas');startRecognition();}else if(action==='drawing'){setPage('canvas');setTool('ai-drawing');}}
function closeModal(){document.getElementById('modal-scrim').hidden=true;if(recognitionSelection)activeRecognitionRequestId=0;recognitionSelection=null;document.getElementById('recognition-box').classList.remove('visible');document.getElementById('sidebar').classList.remove('mobile-visible');}
function showSearch(){setPage('canvas');setModal('Search your notebooks','MARGIN · NOTE SEARCH',`<input id="search-query" class="modal-search" placeholder="Try ‘where did I use substitution?’" autofocus><div class="search-results" id="search-results"></div><p class="modal-hint">Searches typed text, equations, code and OCR-independent ink labels across local notebooks.</p>`);const input=document.getElementById('search-query');input.focus();input.addEventListener('input',()=>searchNotes(input.value));}
function searchNotes(query){const results=document.getElementById('search-results');if(!query.trim()){results.replaceChildren();return;}const words=query.toLowerCase().split(/\s+/).filter(Boolean);const matches=[];for(const notebook of books)for(const node of notebook.nodes||[]){const text=node.type==='text'?node.text:node.type==='equation'?node.expr:node.type==='code'?node.code:node.name||'';const score=words.reduce((sum,word)=>sum+(text.toLowerCase().includes(word)?1:0),0);if(score)matches.push({notebook,node,text,score});}matches.sort((a,b)=>b.score-a.score);results.innerHTML=matches.slice(0,20).map(match=>`<button class="search-result" data-book="${escapeHtml(match.notebook.id)}" data-node="${escapeHtml(match.node.id)}"><strong>${escapeHtml(match.notebook.title)} · ${escapeHtml(match.node.type)}</strong>${escapeHtml(match.text.slice(0,130))}</button>`).join('')||'<p class="modal-hint">No matching note content.</p>';results.querySelectorAll('[data-node]').forEach(button=>button.addEventListener('click',()=>{if(book.id!==button.dataset.book)switchBook(button.dataset.book);const node=nodeById(button.dataset.node);if(!node)return;setPage('canvas');closeModal();requestAnimationFrame(()=>{const rect=workspace.getBoundingClientRect();camera.x=rect.width/2-node.x*camera.zoom;camera.y=rect.height/2-node.y*camera.zoom;applyCamera();redrawInk();});}));}
function exportNotebook(){setPage('canvas');setModal('Export notebook','MARGIN · LOCAL EXPORT',`<p class="modal-hint">Exports are generated on this device. PDF opens your browser’s print dialog; choose “Save as PDF”.</p><div class="export-options"><button data-export="markdown">Markdown</button><button data-export="svg">SVG canvas</button><button data-export="png">PNG image</button><button data-export="pdf">Print / PDF</button></div>`);document.querySelectorAll('[data-export]').forEach(button=>button.addEventListener('click',()=>{const format=button.dataset.export;closeModal();if(format==='markdown')exportMarkdown();else if(format==='svg')exportCanvasSvg();else if(format==='png')exportCanvasPng();else if(format==='pdf')printCanvasPdf();}));}
function exportMarkdown(){const text=book.nodes.map(node=>node.type==='text'?node.text:node.type==='equation'?`$${node.expr}$`:node.type==='code'?`\`\`\`js\n${node.code}\n\`\`\``:node.type==='graph'?`Graph: y = ${node.expr}`:node.name||'').filter(Boolean).join('\n\n');const blob=new Blob([`# ${book.title}\n\n${text}\n`],{type:'text/markdown;charset=utf-8'});downloadBlob(blob,`${safeName(book.title)}.md`);}
function xmlEscape(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[char]));}
function canvasSvg(){const nodes=book.nodes||[],strokes=book.strokes||[];const xs=[],ys=[];for(const node of nodes){const w=node.w||420,h=node.type==='graph'?245:node.type==='code'?180:node.type==='media'?300:100;xs.push(node.x-w/2,node.x+w/2);ys.push(node.y-h/2,node.y+h/2);}for(const stroke of strokes)for(const point of stroke.points||[]){xs.push(point.x);ys.push(point.y);}const minX=xs.length?Math.min(...xs)-36:0,minY=ys.length?Math.min(...ys)-36:0,width=Math.max(600,(xs.length?Math.max(...xs)-minX:600)+36),height=Math.max(420,(ys.length?Math.max(...ys)-minY:420)+36);let body=`<rect x="${minX}" y="${minY}" width="${width}" height="${height}" fill="#f4f4f0"/>`;
 for(const node of nodes){const x=node.x,y=node.y,w=node.w||420;if(node.type==='text'){const lines=String(node.text||'').split(/\r?\n/);body+=`<g font-family="Georgia,serif" font-size="16" fill="#35382f">${lines.map((line,index)=>`<text x="${x-w/2}" y="${y+(index-(lines.length-1)/2)*25}">${xmlEscape(line)}</text>`).join('')}</g>`;}else if(node.type==='equation'){body+=`<g><rect x="${x-w/2}" y="${y-38}" width="${w}" height="76" rx="8" fill="white" stroke="#dfe4da"/><text x="${x-w/2+14}" y="${y-12}" font-family="monospace" font-size="10" fill="#82907f">EQUATION</text><text x="${x-w/2+14}" y="${y+15}" font-family="monospace" font-size="16" fill="#30362e">${xmlEscape(node.expr||'')}</text></g>`;}else if(node.type==='graph'){const graphH=205,graphW=w-2;let path='';try{const evaluate=window.MarginMath.compile(node.expr||'sin(x)');for(let i=0;i<=240;i++){const xv=-10+20*i/240,yv=evaluate(xv);if(!Number.isFinite(yv)||Math.abs(yv)>10){path+=' ';continue;}const px=x-w/2+1+i/240*graphW,py=y-graphH/2+graphH/2-yv/7*(graphH/2-14);path+=`${path.trim().endsWith('M')?'':' '} ${i===0||!Number.isFinite(evaluate(-10+20*(i-1)/240))?'M':'L'}${px.toFixed(2)},${py.toFixed(2)}`;}}catch{}body+=`<g><rect x="${x-w/2}" y="${y-graphH/2-20}" width="${w}" height="${graphH+20}" rx="8" fill="white" stroke="#dfe4da"/><text x="${x-w/2+12}" y="${y-graphH/2-5}" font-family="monospace" font-size="11" fill="#52684f">y = ${xmlEscape(node.expr||'')}</text><path d="${path}" fill="none" stroke="#477a55" stroke-width="2"/></g>`;}else if(node.type==='code'){body+=`<g><rect x="${x-w/2}" y="${y-75}" width="${w}" height="150" rx="8" fill="#fff" stroke="#dfe4da"/><text x="${x-w/2+12}" y="${y-52}" font-family="monospace" font-size="10" fill="#52684f">CALCULATION</text>${String(node.code||'').split(/\r?\n/).slice(0,7).map((line,index)=>`<text x="${x-w/2+12}" y="${y-28+index*17}" font-family="monospace" font-size="10" fill="#454a41">${xmlEscape(line)}</text>`).join('')}</g>`;}else if(node.type==='media'&&node.mime?.startsWith('image/')&&String(node.data||'').startsWith('data:image/')){body+=`<image href="${xmlEscape(node.data)}" x="${x-w/2}" y="${y-130}" width="${w}" height="260" preserveAspectRatio="xMidYMid meet"/>`;}}
 for(const stroke of strokes){if(!stroke.points?.length)continue;const d=stroke.points.map((point,index)=>`${index?'L':'M'}${point.x},${point.y}`).join(' ');body+=`<path d="${d}" fill="none" stroke="${xmlEscape(stroke.color||'#315e4c')}" stroke-width="${Number(stroke.width)||2}" stroke-linecap="round" stroke-linejoin="round"/>`;}
 return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${Math.ceil(width)}" height="${Math.ceil(height)}" viewBox="${minX} ${minY} ${width} ${height}"><title>${xmlEscape(book.title)}</title>${body}</svg>`;}
function exportCanvasSvg(){downloadBlob(new Blob([canvasSvg()],{type:'image/svg+xml;charset=utf-8'}),`${safeName(book.title)}.svg`);}
function exportCanvasPng(){const svgUrl=URL.createObjectURL(new Blob([canvasSvg()],{type:'image/svg+xml;charset=utf-8'})),image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=Math.min(4096,image.naturalWidth);canvas.height=Math.min(4096,image.naturalHeight);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{if(blob)downloadBlob(blob,`${safeName(book.title)}.png`);URL.revokeObjectURL(svgUrl);},'image/png');};image.onerror=()=>URL.revokeObjectURL(svgUrl);image.src=svgUrl;}
function printCanvasPdf(){const popup=window.open('','_blank');if(!popup){addChat('assistant','Allow pop-ups to open the print view, then choose “Save as PDF”.');return;}popup.document.open();popup.document.write(`<!doctype html><html><head><title>${xmlEscape(book.title)}</title><style>body{margin:0;font:12px sans-serif}svg{width:100%;height:auto;max-height:100vh;object-fit:contain}@page{margin:10mm}</style></head><body>${canvasSvg()}<script>addEventListener('load',()=>setTimeout(()=>print(),250))<\/script></body></html>`);popup.document.close();}
function safeName(text){return text.replace(/[^\w-]+/g,'-').replace(/^-|-$/g,'')||'margin-notebook';}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportSelectionLatex(){const output=selectedLatex();if(!output){addChat('assistant','Select one or more notes or equations first.');return;}setModal('Copy LaTeX','MARGIN · SELECTION',`<pre class="latex-output" id="latex-output">${escapeHtml(output)}</pre><div class="modal-actions"><button id="copy-latex">Copy LaTeX</button><button id="download-latex">Download .tex</button></div>`);document.getElementById('copy-latex').onclick=async()=>{try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard access is unavailable in this browser.');await navigator.clipboard.writeText(output);document.getElementById('copy-latex').textContent='Copied';}catch(error){document.getElementById('latex-output').textContent=`${output}\n\nCopy unavailable: ${error.message}`;}};document.getElementById('download-latex').onclick=()=>downloadBlob(new Blob([output],{type:'text/plain'}),'selection.tex');}
async function importFiles(files){for(const file of files){const center=worldCenter();if(file.type==='text/plain'||file.name.toLowerCase().endsWith('.md')){const text=await file.text();addNode('text',{x:center.x,y:center.y,w:480,text:`${file.name}\n\n${text}`});continue;}if(file.type.startsWith('image/')){if(file.size>20*1024*1024){addChat('assistant',`${file.name} is too large to store in the local notebook (20 MB limit).`);continue;}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});pushUndo();book.nodes.push({id:`media-${Date.now()}-${Math.random()}`,type:'media',x:center.x,y:center.y,w:450,name:file.name,mime:file.type,data});save();renderNodes();updateContext();continue;}if(file.type==='application/pdf'){if(file.size>20*1024*1024){addChat('assistant',`${file.name} is too large to store in the local notebook (20 MB limit).`);continue;}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});pushUndo();book.nodes.push({id:`media-${Date.now()}-${Math.random()}`,type:'media',x:center.x,y:center.y,w:490,name:file.name,mime:file.type,data});renderNodes();save();updateContext();}else{addNode('text',{x:center.x,y:center.y,w:450,text:`Imported file: ${file.name}\nThis format is not previewable here; it is not uploaded.`});}}}
function openImport(){setPage('canvas');setModal('Bring your materials','MARGIN · IMPORT',`<div class="import-drop">Drop a PDF, image, text or Markdown file here.<button id="choose-files">Choose files</button><p>Files are read locally; nothing uploads.</p></div>`);document.getElementById('choose-files').onclick=()=>{closeModal();const picker=document.getElementById('file-input');picker.click();};const drop=document.querySelector('.import-drop');drop.addEventListener('dragover',event=>{event.preventDefault();event.dataTransfer.dropEffect='copy';});drop.addEventListener('drop',event=>{event.preventDefault();const files=Array.from(event.dataTransfer.files||[]);if(!files.length)return;closeModal();importFiles(files).catch(error=>addChat('assistant',`Import failed: ${error.message}. Existing notes remain saved.`));});}
function runCodeCell(node,element){const output=element.querySelector('.code-output'),plotCanvas=element.querySelector('canvas');try{const values=Object.create(null),logs=[];let plotExpression='';for(const rawLine of (node.code||'').split(/\r?\n/)){const line=rawLine.replace(/\/\/.*$/,'').trim();if(!line)continue;const plotMatch=line.match(/^plot\s*\(\s*(['"])([^'"]+)\1\s*\)$/);if(plotMatch){plotExpression=plotMatch[2];continue;}const logMatch=line.match(/^console\.log\((.*)\)$/);if(logMatch){const value=logMatch[1].trim();if((value.startsWith('"')&&value.endsWith('"'))||(value.startsWith("'")&&value.endsWith("'")))logs.push(value.slice(1,-1));else if(Object.hasOwn(values,value))logs.push(String(values[value]));else logs.push(String(evaluateCellExpression(value,values)));continue;}const assignment=line.match(/^(?:(?:const|let|var)\s+)?([A-Za-z_]\w*)\s*=\s*(.+)$/);if(!assignment)throw new Error('Use assignments, console.log(...), or plot("expression").');values[assignment[1]]=evaluateCellExpression(assignment[2],values);}output.textContent=logs.join('\n')||Object.entries(values).map(([name,value])=>`${name} = ${value}`).join('\n')||'Cell ran · no output';output.style.color='#63755f';node.lastOutput=output.textContent;if(plotExpression){plotCanvas.hidden=false;window.MarginMath.plot(plotCanvas,plotExpression);}}catch(error){output.textContent=`Check cell: ${error.message}`;output.style.color='#b2654c';}}
function evaluateCellExpression(expression,values){const expanded=expression.replace(/\b[A-Za-z_]\w*\b/g,name=>Object.hasOwn(values,name)?`(${values[name]})`:name);const value=window.MarginMath.compile(expanded)(0);if(!Number.isFinite(value))throw new Error('Expression is undefined or non-finite.');return value;}
function updateContext(){const title=book.title;const textNodes=book.nodes.filter(node=>node.type==='text').length,equations=book.nodes.filter(node=>node.type==='equation').length;document.getElementById('context-summary').textContent=title;document.getElementById('context-detail').textContent=`${textNodes} text cards · ${equations} equations · ${book.strokes?.length||0} ink strokes`;document.getElementById('insight-copy').textContent=`${book.strokes?.length||0} ink strokes · ${textNodes} text notes · ${equations} equations. Choose Read ink to transcribe a line or AI sketch to ask about a crop.`;}
function scheduleCheck(){clearTimeout(mathRequestTimer);mathRequestTimer=setTimeout(()=>{for(const node of book.nodes.filter(item=>item.type==='equation')){const el=nodesLayer.querySelector(`[data-id="${node.id}"]`);if(el)checkEquationNode(node,el);}updateContext();save();},500);}
async function askAssistant(prompt){const clean=prompt.trim();if(!clean)return;addChat('user',clean);const note=book.nodes.map(node=>node.type==='text'?node.text:node.type==='equation'?`Equation: ${node.expr}`:node.type==='code'?`Code: ${node.code}`:'').filter(Boolean).join('\n\n');if(!aiReady){addChat('assistant',localStudyReply(clean,note));return;}if(!document.getElementById('ai-opt-in').checked){addChat('assistant','Turn on “Allow AI to read this notebook” before using provider-powered help. Your notes remain local until you opt in.');return;}try{const response=await fetch('/api/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'chat',prompt:clean,note:note.slice(0,12000)})});const data=await response.json();if(!response.ok)throw new Error(data.error||'AI request failed');addChat('assistant',data.answer);}catch(error){addChat('assistant',`Could not reach AI: ${error.message}. Your notes are still saved locally.`);}}
function selectedInkImage(rect){const padding=18,maxDimension=1200,scale=Math.max(.25,Math.min(2,maxDimension/Math.max(1,rect.w+padding*2),maxDimension/Math.max(1,rect.h+padding*2))),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.ceil((rect.w+padding*2)*scale));canvas.height=Math.max(1,Math.ceil((rect.h+padding*2)*scale));const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,canvas.width,canvas.height);c.save();c.scale(scale,scale);c.translate(padding-rect.x,padding-rect.y);c.beginPath();c.rect(rect.x-padding,rect.y-padding,rect.w+padding*2,rect.h+padding*2);c.clip();for(const stroke of book.strokes||[]){if(!stroke.points?.length)continue;c.beginPath();c.strokeStyle=stroke.color||'#111';c.lineWidth=stroke.width||2;c.lineCap='round';c.lineJoin='round';let started=false;for(const point of stroke.points){if(point.x>=rect.x-padding&&point.x<=rect.x+rect.w+padding&&point.y>=rect.y-padding&&point.y<=rect.y+rect.h+padding){if(!started){c.moveTo(point.x,point.y);started=true;}else c.lineTo(point.x,point.y);}else started=false;}c.stroke();}for(const node of book.nodes){const bounds=nodeBounds(node);if(bounds.x>rect.x+rect.w||bounds.x+bounds.w<rect.x||bounds.y>rect.y+rect.h||bounds.y+bounds.h<rect.y)continue;const x=node.x,y=node.y,width=node.w||420;if(node.type==='text'){c.fillStyle='#111';c.font=node.style==='title'?'bold 22px Georgia':'16px Georgia';String(node.text||'').split(/\r?\n/).forEach((line,index)=>c.fillText(line,x-width/2,y-((String(node.text||'').split(/\r?\n/).length-1)*12)+index*25));}else if(node.type==='equation'){c.fillStyle='#111';c.font='16px monospace';c.fillText(node.expr||'',x-width/2+12,y+5);}else if(node.type==='graph'){c.fillStyle='#111';c.font='14px monospace';c.fillText(`y = ${node.expr||'sin(x)'}`,x-width/2+10,y-90);}}c.restore();return canvas.toDataURL('image/png');}
function prepareDrawingAnalysis(rect){const image=selectedInkImage(rect);if(image.length>3_900_000){addChat('assistant','That crop is too large to share. Draw a tighter selection around the relevant sketch or equation.');return;}const nearby=book.nodes.filter(node=>{const bounds=nodeBounds(node);return bounds.x<=rect.x+rect.w&&bounds.x+bounds.w>=rect.x&&bounds.y<=rect.y+rect.h&&bounds.y+bounds.h>=rect.y;}).map(node=>node.type==='text'?node.text:node.type==='equation'?`Equation: ${node.expr}`:'').filter(Boolean).join('\n');setModal('Ask about this drawing','AI SKETCH · IMAGE SHARING REQUIRES OPT-IN',`<div class="recognition-notice">The selected crop contains your notebook ink. It stays on this device unless you enable the AI opt-in below and submit it; then the crop and your question go to the configured AI provider.</div><img class="recognition-preview" src="${image}" alt="Selected drawing crop"><label class="recognition-form">What should AI look for?<textarea id="drawing-prompt" placeholder="Explain the diagram, check this step, or suggest what to label…">Describe this sketch or worked step. Explain what you can infer and mention any uncertainty.</textarea></label><div class="modal-hint" id="drawing-status">${visionReady?'Ready when you are.':aiReady?'Text AI is configured, but the selected model may not support images. Choose a vision-capable model.':'No AI provider is configured on this server; local canvas tools still work.'}</div><div class="modal-actions"><button id="drawing-ask" ${visionReady?'':'disabled'}>Ask AI about this</button><button id="drawing-close">Close</button></div>`);document.getElementById('drawing-close').onclick=closeModal;document.getElementById('drawing-ask').onclick=()=>askAboutDrawing(image,nearby);}
async function askAboutDrawing(image,nearby=''){const status=document.getElementById('drawing-status'),button=document.getElementById('drawing-ask'),prompt=document.getElementById('drawing-prompt')?.value.trim();if(!prompt){status.textContent='Enter a question about the drawing first.';return;}if(!visionReady){status.textContent='A vision-capable AI model is not configured on this server. No drawing was sent.';return;}if(!document.getElementById('ai-opt-in').checked){status.textContent='Turn on “Allow AI to read this notebook’s typed text” in the assistant panel before sharing the drawing. Nothing has been sent.';return;}button.disabled=true;status.textContent='Sending the selected crop to your configured AI provider…';try{const response=await fetch('/api/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'drawing',prompt,note:nearby.slice(0,12000),image})});const data=await response.json();if(!response.ok)throw new Error(data.error||'AI drawing analysis failed.');status.textContent=data.local?'Visual AI needs a configured vision-capable provider. The drawing stayed on this device.':data.answer; if(!data.local)addChat('assistant',`AI sketch · ${data.answer}`);}catch(error){status.textContent=`Could not analyze this drawing: ${error.message}. It remains saved locally.`;}finally{if(button.isConnected)button.disabled=false;}}
function addChat(role,text){const message=document.createElement('div');message.className=`chat-message ${role}`;if(role==='assistant'){const label=document.createElement('strong');label.textContent='Margin';message.append(label);}message.append(document.createTextNode(text));chat.append(message);chat.scrollTop=chat.scrollHeight;}
function localStudyReply(prompt,note){const lower=prompt.toLowerCase();if(lower.includes('practice')||lower.includes('exam'))return `Practice set · ${book.title}\n\n1. State the main rule you used in your notes.\n2. Apply it to a new example without looking.\n3. Explain why each transition is valid.\n\nI made these from your notebook structure; they are prompts from your notes, not verified exam questions.`;if(lower.includes('summar'))return `Canvas summary (local):\n${note.slice(0,700)||'No typed notes yet. Add a text card or equation first.'}`;if(lower.includes('hint')||lower.includes('next'))return note?`Hint: focus on the most recent equation or line. Ask what operation would preserve equality on both sides. Your note context starts with “${note.slice(-240)}”`:'Add an equation or notes first, then I can offer a contextual next-step hint.';return `I can see ${book.nodes.length} canvas objects and ${book.strokes?.length||0} ink strokes. Use Read ink to transcribe one handwritten prose line locally; math notation may need manual correction. Connect your own AI provider to ask open-ended questions over your notes.`;}
function openPractice(){setPage('canvas');const content=book.nodes.map(node=>node.type==='text'?node.text:node.type==='equation'?node.expr:'').filter(Boolean).join('\n');setModal('Practice set','MARGIN · STUDY',`<p class="modal-hint">Drafted locally from <strong>${escapeHtml(book.title)}</strong>. Use as study prompts; answers are not generated or verified here.</p><pre class="exam-output">1. Explain the key idea in your own words.\n2. Recreate one worked example without looking.\n3. Identify a likely sign or arithmetic slip in a new step.\n4. What question do you still have about:\n${escapeHtml(content.slice(0,240)||'your current topic')}\n\nShow your working and check each line.</pre><div class="modal-actions"><button id="insert-practice">Add set to canvas</button></div>`);document.getElementById('insert-practice').onclick=()=>{const center=worldCenter();addNode('text',{x:center.x,y:center.y,w:420,text:'Practice set\n\n1. Explain the key idea in your own words.\n2. Recreate one worked example without looking.\n3. Find a likely arithmetic or sign slip in a new step.\n4. What question do you still have?'});closeModal();};}
function addGraph(){const node=addNode('graph',{expr:'sin(x)',w:390});selectedIds=new Set([node.id]);showSelection();}
function addCode(){addNode('code',{code:'// Safe local math cell\nconst radius = 3\nconst area = pi * radius^2\nconsole.log(area)\nplot("sin(x)")',w:420});}
function bindEvents(){document.querySelectorAll('[data-tool]').forEach(button=>button.addEventListener('click',()=>button.dataset.tool==='recognize'?startRecognition():setTool(button.dataset.tool)));document.querySelectorAll('.workspace-tab').forEach(tab=>tab.addEventListener('click',()=>setPage(tab.dataset.page)));document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>button.dataset.action==='new-notebook'?document.getElementById('new-note').click():runStudyAction(button.dataset.action)));for(const id of ['account-open','sidebar-account'])document.getElementById(id).addEventListener('click',()=>openAccount());document.getElementById('new-note').addEventListener('click',()=>{save();const next={id:`book-${Date.now()}`,title:'Untitled notebook',icon:'✎',nodes:[],strokes:[]};books.unshift(next);book=next;selectedIds.clear();undoStack=[];editingSnapshot=null;document.getElementById('undo-button').disabled=true;renderBooks();renderNodes();const center=worldCenter();addNode('text',{x:center.x,y:center.y,w:440,text:'New notebook',style:'title'});renderLibrary();});document.getElementById('add-notebook').addEventListener('click',()=>document.getElementById('new-note').click());document.getElementById('add-text').addEventListener('click',()=>addNode('text',{text:''}));document.getElementById('add-equation').addEventListener('click',()=>addNode('equation',{expr:''}));document.getElementById('add-graph').addEventListener('click',addGraph);document.getElementById('add-code').addEventListener('click',addCode);document.getElementById('undo-button').addEventListener('click',undo);document.getElementById('zoom-in').addEventListener('click',()=>zoomCenter(1.15));document.getElementById('zoom-out').addEventListener('click',()=>zoomCenter(1/1.15));document.getElementById('zoom-home').addEventListener('click',fitCanvas);document.getElementById('search-open').addEventListener('click',showSearch);document.getElementById('assistant-open').addEventListener('click',()=>{setPage('canvas');const panel=document.getElementById('assistant-panel');panel.classList.remove('closed');if(innerWidth<=620)panel.classList.add('mobile-open');});document.getElementById('assistant-body').addEventListener('scroll',()=>document.getElementById('insight-card').setAttribute('aria-label','Study suggestions for this notebook'));document.getElementById('import-open').addEventListener('click',openImport);document.getElementById('file-input').addEventListener('change',event=>{const files=Array.from(event.target.files||[]);event.target.value='';importFiles(files).catch(error=>addChat('assistant',`Import failed: ${error.message}. Your existing notebook was not changed.`));});document.getElementById('export-button').addEventListener('click',exportNotebook);document.getElementById('practice-button').addEventListener('click',openPractice);document.querySelectorAll('[data-prompt]').forEach(button=>button.addEventListener('click',()=>askAssistant(button.dataset.prompt)));document.getElementById('send-chat').addEventListener('click',()=>{const value=chatInput.value;chatInput.value='';askAssistant(value);});chatInput.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();document.getElementById('send-chat').click();}});document.getElementById('ai-opt-in').addEventListener('change',event=>{localStorage.setItem('margin-ai-opt-in',String(event.target.checked));if(event.target.checked&&!aiReady){addChat('assistant','No server-side AI provider is configured. Local study tools stay free and private.');}});document.getElementById('ai-opt-in').checked=localStorage.getItem('margin-ai-opt-in')==='true';document.getElementById('selection-done').addEventListener('click',()=>{selectedIds.clear();showSelection();});document.getElementById('selection-latex').addEventListener('click',exportSelectionLatex);document.getElementById('selection-delete').addEventListener('click',()=>{if(!selectedIds.size)return;pushUndo();book.nodes=book.nodes.filter(node=>!selectedIds.has(node.id));selectedIds.clear();showSelection();save();updateContext();});document.getElementById('modal-close').addEventListener('click',closeModal);document.getElementById('page-canvas').setAttribute('aria-label','Canvas workspace');document.getElementById('page-library').setAttribute('aria-label','Notebook library');document.getElementById('page-study').setAttribute('aria-label','Study desk');document.getElementById('page-settings').setAttribute('aria-label','Settings');document.getElementById('modal-scrim').addEventListener('click',event=>{if(event.target.id==='modal-scrim')closeModal();});document.getElementById('toggle-assistant').addEventListener('click',()=>{setPage('canvas');const panel=document.getElementById('assistant-panel');if(innerWidth<=620)panel.classList.toggle('mobile-open');else panel.classList.toggle('closed');});document.getElementById('assistant-close').addEventListener('click',()=>{const panel=document.getElementById('assistant-panel');if(innerWidth<=620)panel.classList.remove('mobile-open');else panel.classList.toggle('closed');});document.querySelector('.brand').addEventListener('click',event=>{event.preventDefault();setPage('canvas');fitCanvas();});document.getElementById('mobile-menu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('mobile-visible'));document.getElementById('sidebar').addEventListener('click',event=>{if(innerWidth<=620&&event.target.closest('.note-item'))document.getElementById('sidebar').classList.remove('mobile-visible');});workspace.addEventListener('pointerdown',pointerDown);workspace.addEventListener('pointermove',pointerMove);workspace.addEventListener('pointerup',pointerUp);workspace.addEventListener('pointercancel',pointerUp);workspace.addEventListener('wheel',event=>{if(event.ctrlKey||event.metaKey){event.preventDefault();zoomAt(event.deltaY<0?1.08:.92,event.clientX,event.clientY);}},{passive:false});window.addEventListener('resize',()=>{resizeInk();renderNodes();});window.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='n'){event.preventDefault();document.getElementById('new-note').click();}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();showSearch();}if((event.metaKey||event.ctrlKey)&&event.key==='Enter'){event.preventDefault();chatInput.focus();}if(event.key==='Escape'&&!document.getElementById('modal-scrim').hidden)closeModal();if(!event.target.matches('input,textarea,[contenteditable=true]')){if(event.key.toLowerCase()==='v'){setPage('canvas');setTool('select');}if(event.key.toLowerCase()==='p'){setPage('canvas');setTool('pen');}if(event.key.toLowerCase()==='h'){setPage('canvas');setTool('highlighter');}if(event.key.toLowerCase()==='e'){setPage('canvas');setTool('eraser');}if(event.key.toLowerCase()==='l'){setPage('canvas');setTool('lasso');}if(event.key.toLowerCase()==='a'){setPage('canvas');setTool('ai-drawing');}if((event.key==='Delete'||event.key==='Backspace')&&selectedIds.size){event.preventDefault();document.getElementById('selection-delete').click();}}});}
function zoomCenter(factor){const rect=workspace.getBoundingClientRect();zoomAt(factor,rect.left+rect.width/2,rect.top+rect.height/2);}
function zoomAt(factor,x,y){const rect=workspace.getBoundingClientRect();const px=x-rect.left,py=y-rect.top;const next=Math.max(.3,Math.min(2.5,camera.zoom*factor));const ratio=next/camera.zoom;camera.x=px-(px-camera.x)*ratio;camera.y=py-(py-camera.y)*ratio;camera.zoom=next;applyCamera();redrawInk();}
function fitCanvas(){const bounds=[];for(const node of book.nodes)bounds.push(nodeBounds(node));for(const stroke of book.strokes||[])for(const point of stroke.points||[])bounds.push({x:point.x-8,y:point.y-8,w:16,h:16});if(!bounds.length){camera={x:workspace.clientWidth/2,y:workspace.clientHeight/2,zoom:1};}else{const left=Math.min(...bounds.map(item=>item.x)),top=Math.min(...bounds.map(item=>item.y)),right=Math.max(...bounds.map(item=>item.x+item.w)),bottom=Math.max(...bounds.map(item=>item.y+item.h));camera.zoom=Math.max(.3,Math.min(1.6,(workspace.clientWidth-90)/Math.max(360,right-left),(workspace.clientHeight-110)/Math.max(260,bottom-top)));camera.x=workspace.clientWidth/2-(left+right)/2*camera.zoom;camera.y=workspace.clientHeight/2-(top+bottom)/2*camera.zoom;}applyCamera();redrawInk();}
function setAiStatus(){fetch('/api/status',{cache:'no-store'}).then(response=>response.json()).then(data=>{aiReady=Boolean(data.configured);visionReady=Boolean(data.visionConfigured);const badge=document.getElementById('ai-status');badge.textContent=aiReady?'AI ready · opt-in':'AI off · local mode';badge.title=visionReady?'AI can process selected drawing crops after you opt in':aiReady?'Text AI is configured; select a vision-capable model for image analysis':'Add your server AI endpoint and key in .env to enable AI';document.getElementById('assistant-presence').textContent=aiReady?'Connected · sharing only after opt-in':'Local study companion';for(const button of document.querySelectorAll('[data-tool="ai-drawing"]'))button.title=visionReady?'Select an area to ask your configured model about a sketch':aiReady?'Select a crop; configure a vision-capable model to analyze it':'Configure an AI provider in .env to enable image analysis';}).catch(()=>{aiReady=false;visionReady=false;document.getElementById('ai-status').textContent='AI off · local mode';});}
renderBooks();renderNodes();bindEvents();resizeInk();applyCamera();updateContext();renderLibrary();updateAccountUi();initializeAccount();setAiStatus();
